-- ==================== V2.5 迁移预检（Part B 前执行；只读） ====================
-- (1) 迁移涉及 4 表的索引清单：若存在包含 device 的唯一索引，先评估迁移冲突再执行 Part B
SELECT tablename, indexname, indexdef FROM pg_indexes
 WHERE schemaname = 'qixiao-apaas'
   AND tablename IN ('t_auto_hltgq_water_river_info','t_auto_hltgq_water_wt_nfo','t_auto_hltgq_water_rain_info','t_auto_hltgq_water_soil_data')
 ORDER BY tablename, indexname;
-- (2) 迁移两端同站码同时刻并存检查（期望全部 0 行；非 0 = 迁入合并后出现重复观测，需先定保留策略）：
SELECT 'river_info' AS tbl, "STCD", tm, count(*) AS dup FROM "qixiao-apaas".t_auto_hltgq_water_river_info
 WHERE device IN ('rc1K7YTevDsijI9KNT2c', 'KAQvRagQeQTMcrFSdugG', 'fj2w748fRb1DqE8o1UeJ', 'TSOAI3Csv8PQgmP3xJGz', 'MGp6VKLfc1HEewvF5L3U', 'ryohzrcLFUtmVeyKAskw', 'l7Z6s8wZJEtquid0H368', 'htPg3LAODF2AB6JA1cCA', 'QyVWCC61z6eTqnbvue1T', 'n0SXPEVRzbdXzOjM3hLg', 'x7UYsXbEIKW6Zpor3veJ', 'xixeDAQWFcKqONiMLPqy', 'yLCKLUJO6sMHfqfjZa2N', 'JqwSFmWAj62FaHIWttXo', 's0r6c5iBNrMVvLVn2qJY', 'U3ReNoiudbIo8a3NIU91', 'CkiqsQAKhyOlgE7hu0cO', 'rKtIYQgBOhZocM3n8Jaw', 'kSp5RsyI8jvGh5qpOyu3', 'gV1hX85dDIrG1JQHc5pf', 'MWhphYu5qhN7oZGIy4ZI', 'aenKjVkmouBS0Eu801ZZ', 'Asb5vQA1uSgEjle7S2rE', 'BJ8VPeQtqCK1cSgrArYE', 'zm9XiobxV0V3DTzLDSwS', 'V8uN0oPxfH036lOywfhR') AND "STCD" IS NOT NULL AND "STCD" <> ''
